// Extract the incoming payload from webhook
const body = $input.first().json.body || $input.first().json;

const jobId = body.job_id || 'unknown';
const agentParams = body.agent_parameters || {};
const jobFields = body.job_fields || {};

// Validate required parameter
const apiKey = agentParams.API_KEY || '';
const lookupCount = parseInt(agentParams.LOOKUP_COUNT || '3', 10);
const notificationEmail = agentParams.NOTIFICATION_EMAIL || 'none';

if (!apiKey) {
  throw new Error('API_KEY parameter is required but was not provided');
}

return [{
  json: {
    job_id: jobId,
    api_key: apiKey,
    lookup_count: lookupCount,
    notification_email: notificationEmail,
    job_fields: jobFields,
    validation: 'passed'
  }
}];

// Get the validated params from Validate Params node
const params = $('Validate Params').first().json;

// Get all fetched users
const users = $input.all().map(item => ({
  name: item.json.name,
  email: item.json.email,
  company: item.json.company?.name || 'N/A',
  city: item.json.address?.city || 'N/A'
}));

return [{
  json: {
    job_id: params.job_id,
    status: 'success',
    contacts_found: users.length,
    contacts: users,
    notification_email: params.notification_email,
    processed_at: new Date().toISOString(),
    message: `Found ${users.length} contacts for job ${params.job_id}`
  }
}];
